package hq4x

import (
	"compress/gzip"
	"encoding/binary"
	"io"
	"os"
	"testing"
)

// The fixture was generated by hqx-java. Each sample contains dimensions,
// wrap flags, source pixels, and every pixel of the expected result.
func TestJavaReference(t *testing.T) {
	f, err := os.Open("testdata/java-hq4x.bin.gz")
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	z, err := gzip.NewReader(f)
	if err != nil {
		t.Fatal(err)
	}
	defer z.Close()
	read := func(v any) {
		t.Helper()
		if err := binary.Read(z, binary.BigEndian, v); err != nil {
			t.Fatal(err)
		}
	}
	var count uint32
	read(&count)
	for sample := uint32(0); sample < count; sample++ {
		var width, height uint32
		var wx, wy bool
		var ty, tu, tv, ta uint32
		read(&width)
		read(&height)
		read(&wx)
		read(&wy)
		read(&ty)
		read(&tu)
		read(&tv)
		read(&ta)
		src := make([]int, int(width*height))
		dst := make([]int, len(src)*16)
		for i := range src {
			var c uint32
			read(&c)
			src[i] = int(c)
		}
		Hq4x_32_rb(src, dst, int(width), int(height), int(ty), int(tu), int(tv), int(ta), wx, wy)
		for i, got := range dst {
			var want uint32
			read(&want)
			if uint32(got) != want {
				t.Fatalf("sample %d (%dx%d, wrap %t/%t), pixel %d: got %08x, want %08x", sample, width, height, wx, wy, i, uint32(got), want)
			}
		}
	}
	if _, err := z.Read(make([]byte, 1)); err != io.EOF {
		t.Fatalf("trailing fixture data: %v", err)
	}
}

func TestAlphaThreshold(t *testing.T) {
	// The alpha values straddle the signed-byte boundary used by Java.
	av, bv := uint32(0x7f123456), uint32(0x80123456)
	a, b := int(av), int(bv)
	if diff(a, b, 48<<16, 7<<8, 6, 1) {
		t.Fatal("alpha values one apart should be within the threshold")
	}
	if !diff(a, b, 48<<16, 7<<8, 6, 0) {
		t.Fatal("different alpha values should exceed a zero threshold")
	}
}

func TestBuffersAndDimensions(t *testing.T) {
	Hq4x_32_rb(nil, nil, 0, 0, 48, 7, 6, 0, false, false)
	cases := []struct {
		w, h      int
		in, out   []int
		threshold int
	}{
		{-1, 1, nil, nil, 0}, {1, 1, nil, make([]int, 16), 0},
		{1, 1, make([]int, 1), make([]int, 15), 0}, {1, 1, make([]int, 1), make([]int, 16), 256},
		{int(^uint(0) >> 1), 2, nil, nil, 0},
	}
	for _, tc := range cases {
		func() {
			defer func() {
				if recover() == nil {
					t.Errorf("expected panic for %+v", tc)
				}
			}()
			Hq4x_32_rb(tc.in, tc.out, tc.w, tc.h, 48, 7, 6, tc.threshold, false, false)
		}()
	}
}
